contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Run a single test: attempt to call sendTo with arbitrary caller (this contract is owner),
    // arbitrary receiver and amount. We observe balances before and after and note whether call reverted.
    function run(address receiver, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // this contract deployed c, so this contract is owner of c; no precondition required
        uint beforeC = address(c).balance;
        uint beforeReceiver = receiver == address(this) ? address(this).balance : receiver.balance;

        bool reverted;
        // Perform the state-changing call as a top-level statement. Transfer no ETH from this test to c.
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;
        uint afterReceiver = receiver == address(this) ? address(this).balance : receiver.balance;

        // General rule:
        // If caller (this contract) is owner and receiver != 0 and amount > 0 then either call reverted == true
        // or balances changed exactly by amount (receiver +amount, c -amount). Otherwise the call must revert and
        // balances must be unchanged.
        bool callerIsOwner = true; // by construction the test contract deployed c and is its owner
        bool paramsValid = (receiver != address(0) && amount > 0);

        assert(
            // when caller is owner and params valid: either reverted or exact transfer
            ((callerIsOwner && paramsValid) && (reverted || (afterC + amount == beforeC && afterReceiver == beforeReceiver + amount)))
            // when caller not owner or params invalid: must revert and balances unchanged
            || ((!callerIsOwner || !paramsValid) && reverted && afterC == beforeC && afterReceiver == beforeReceiver)
        );
    }

    receive() external payable { }
}

